window.kbPageData["views/entry/k-afebf20e30b5ec05"] = {"key":"entry/k-afebf20e30b5ec05","state":{"route":"entry/k-afebf20e30b5ec05"},"node":{"id":"k-afebf20e30b5ec05","mode":"k","title":"两个毫不动摇","type":"制度与规则","domain":"经济","reading":"","intro":"","priority":100,"aliases":["“两个毫不动摇”"],"qs":["政治理论必刷100题#43","江苏 2025 A类 行测#6","江苏 2025 B类 行测#6","江苏 2025 C类 行测#6"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":2,"reviewSet":"多题条目","independentCount":2,"tags":{"专题":["market"],"主类":["制度与规则"],"出处性质":["专项题解析","机构注释"],"学科":["政治理论","经济"],"来源主题":["发展与治理"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"“两个毫不动摇”是坚持和完善社会主义基本经济制度的要求，指毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展。","review":{"title":"两个毫不动摇","type":"制度与规则","definition":"“两个毫不动摇”是坚持和完善社会主义基本经济制度的要求，指毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展。","explanation":"党的二十大报告将坚持和完善社会主义基本经济制度纳入构建高水平社会主义市场经济体制的部署。2024年党的二十届三中全会《决定》进一步明确，保证各种所有制经济依法平等使用生产要素、公平参与市场竞争、同等受到法律保护，促进各种所有制经济优势互补、共同发展。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"构建高水平社会主义市场经济体制"}],"domain":"经济","examFocus":{"政治理论必刷100题#43":"对照进一步全面深化改革的部署，核对改革重点、民营经济立法和不同所有制经济的平等保障。","江苏 2025 A类 行测#6":"按改革举措所针对的对象，核对其在党的二十届三中全会《决定》中的归属。"}},"aspects":[{"title":"经济体制改革重点与民营经济政策","uses":[{"unit":"Q1","role":"直接考查","use":"本题为选非题，选A。2024年党的二十届三中全会《决定》的说明将深化经济体制改革列为进一步全面深化改革的重点，A写成了政治体制改革。B所述制定民营经济促进法是当时提出的举措，C、D分别对应2025年2月17日民营企业座谈会讲话中的平等保障和政策延续要求。","evidence":"深化政治体制改革是进一步全面深化改革的重点","qids":["政治理论必刷100题#43"]}]},{"title":"高水平社会主义市场经济体制的举措","uses":[{"unit":"Q2","role":"直接考查","use":"本题同选D。按2024年党的二十届三中全会《决定》的篇章归属，③落实“两个毫不动摇”，与②构建全国统一大市场、④完善产权制度同属构建高水平社会主义市场经济体制的举措。①培育壮大先进制造业集群归入健全推动经济高质量发展体制机制。","evidence":"坚持和落实“两个毫不动摇”，促进各种所有制经济优势互补、共同发展","qids":["江苏 2025 A类 行测#6","江苏 2025 B类 行测#6","江苏 2025 C类 行测#6"]}]}],"sources":[{"id":"39174200a2f5f745","label":"“两个毫不动摇”","topic":"发展与治理","category":"非时政","text":"1.“两个毫不动摇”\n即“毫不动摇巩固和发展公有制经济”“毫不动摇鼓励、支持、引导非公有制经济发\n展”。\n党的十六大提出：“必须毫不动摇地巩固和发展公有制经济”“必须毫不动摇地鼓励、\n支持和引导非公有制经济发展”。党的十八大进一步提出：“毫不动摇鼓励、支持、引导非\n公有制经济发展，保证各种所有制经济依法平等使用生产要素、公平参与市场竞争、同等受\n到法律保护。”\n党的十九大把“两个毫不动摇”写入新时代坚持和发展中国特色社会主义的基本方略，\n作为党和国家一项大政方针进一步确定下来。党的二十大提出：“坚持和完善社会主义基本\n经济制度，毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发\n展”。","source":{"doc":"6cbfb01fe723bba64b75","first":29,"last":29,"page":29,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#43":{"paper":"政治理论必刷100题","n":43,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",13],"asrc":["国省考政治理论必刷100题.pdf",58],"card":"6365c94ac9ad29de0b4faff0","links":[{"id":"k-afebf20e30b5ec05","role":"直接考查","why":"考查落实“两个毫不动摇”对各类所有制经济提供的平等保障。"}]},"江苏 2025 A类 行测#6":{"paper":"江苏 2025 A类 行测","n":6,"mod":"政治理论","src":["98687766ac277f427cd6.pdf",2],"asrc":["4fe8e0544dd7b47699d2.pdf",3],"card":"1b4efc1ea7c5fb799d708f3e","links":[{"id":"k-afebf20e30b5ec05","role":"直接考查","why":"考查促进各种所有制经济优势互补、共同发展的制度要求。"}]},"江苏 2025 B类 行测#6":{"paper":"江苏 2025 B类 行测","n":6,"mod":"政治理论","src":["91e0d9fd02ca7ec6d61f.pdf",2],"asrc":["f2ff67a0f2a2f7e8e926.pdf",3],"card":"aca47d95f03ee53d99c8e0d3","links":[{"id":"k-afebf20e30b5ec05","role":"直接考查","why":"巩固和发展公有制经济以及鼓励、支持、引导非公有制经济发展，属于该部分的改革要求。"}]},"江苏 2025 C类 行测#6":{"paper":"江苏 2025 C类 行测","n":6,"mod":"政治理论","src":["ffc394a1c160f331ec57.pdf",2],"asrc":["d1de3b437151c05b769e.pdf",3],"card":"233392ae527e2b0d3e48fb77","links":[{"id":"k-afebf20e30b5ec05","role":"直接考查","why":"巩固和发展公有制经济、鼓励支持引导非公有制经济发展是构建高水平社会主义市场经济体制的要求。"}]}},"terms":{},"references":{"twenty":{"name":"党的二十大报告（2022年）","url":"https://www.miit.gov.cn/xwdt/szyw/art/2022/art_d664717b51f54b9886bc371c5f3594ed.html"}},"topics":[{"slug":"market","title":"统一大市场与公平竞争"}],"units":{"k-afebf20e30b5ec05":[["政治理论必刷100题#43"],["江苏 2025 A类 行测#6","江苏 2025 B类 行测#6","江苏 2025 C类 行测#6"]]}};
